import 'package:flutter/material.dart';import '../models/billing.dart';import '../services/billing_service.dart';class BillingModulesScreen extends StatefulWidget{const BillingModulesScreen({super.key});@override State<BillingModulesScreen> createState()=>_S();}class _S extends State<BillingModulesScreen>{final service=BillingService();late Future<List<BillingModule>> future;@override void initState(){super.initState();future=service.modules();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Billing Modules')),body:FutureBuilder<List<BillingModule>>(future:future,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((m)=>Card(child:ListTile(leading:Icon(m.active?Icons.check_circle:Icons.block),title:Text(m.name),subtitle:Text('${m.code} • ${m.description??''}')))).toList());}));}